          "type": "integer",
          "description": "Number of messages per page. Defaults to 20, maximum 100."
        },
        "search": {
          "type": "string",
          "description": "Optional case-insensitive text to search for inside message content. Omit to return all messages."
        },
        "include_debug": {
          "type": "boolean",
          "description": "Include tool-call cards and internal flow messages in the result. Defaults to false; these rows can be very large and normally hide the conversation itself."
        }
      },
      "required": []
    }
  }
}

