{
  "type": "function",
  "function": {
    "name": "memory_write",
    "description": "Save a note about this user for this agent, or replace one already stored. The note belongs to the user and the agent together, not to the conversation: it is read back by this agent in any of this user's chats, and is invisible to other users and to other agents. Use it for durable facts worth carrying between conversations - what the user prefers, decisions that were made, ids, endpoints or quirks that were hard to find, and what a repeated task needs to know. Keep the note short and self-contained - write several small notes rather than one long report. Pass memory_id to edit a note stored earlier (ids come from memory_lookup); leave it out to add a new note. Agent and user ids come from the run, so a note can only ever be written for the current user by the current agent.",
    "parameters": {
      "type": "object",
      "properties": {
        "note": {
          "type": "string",
          "description": "The text to store, up to 4000 characters. Write it so it still makes sense on its own, without the conversation around it. When editing, this replaces the whole note."
        },
        "memory_id": {
          "type": "integer",
          "description": "The id of a note this agent stored earlier about this user, as returned by memory_lookup. Omit to add a new note instead of editing one. An id belonging to another user or another agent reads as not found."
        }
      },
      "required": [
        "note"
      ]
    }
  }
}

{
  "type": "function",
  "function": {
    "name": "memory_lookup",
    "description": "Read back the notes this agent has stored about this user with memory_write, newest first. Check it before asking the user something they may have already answered, and at the start of work these two have already covered - the notes follow the user across their chats, so what an earlier conversation taught this agent is here too. An optional search matches text inside the notes, and limit caps how many come back. Only notes this agent wrote about this user are returned, so nothing belonging to another user or another agent is visible.",
    "parameters": {
      "type": "object",
      "properties": {
        "search": {
          "type": "string",
          "description": "Optional case-insensitive text to look for inside the notes. Omit to return the most recent notes."
        },
        "limit": {
          "type": "integer",
          "description": "How many notes to return, newest first. Defaults to 20, maximum 100."
        }
      },
      "required": []
    }
  }
}

{
  "type": "function",
  "function": {
    "name": "environment_info",
    "description": "Describe the environment this call is running in: the project, the agent, the chat, the machine's location and the current time. Everything except the location is taken from the run, so this is how an agent learns which project it is working in, which chat it is answering in, who owns that chat and which country that owner registered from, how many messages the chat holds, which agents, tables and members the project has, which skills and tools the agent itself has, how many notes that agent has stored about the user it is answering, and how many that agent has written in total. It also reports the current time in UTC and in the backend's own timezone, and the backend's approximate physical location by looking up its own egress IP - note that this is the server's location, identical for every chat and not the user's. The location lookup is best effort and bounded, and reports available=false with a reason if it cannot complete. Use it when the user asks which project or chat this is, what time it is, where the system runs, when you need an id to report back, or to check your own configuration before relying on a skill or tool. Takes no arguments, and can only ever report the caller's own environment. Project agents and members are listed with their integer id, which is what a tool that takes an agent id - call_agent - needs.",
    "parameters": {
      "type": "object",
      "properties": {},
      "required": []
    }
  }
}

